mapper.select:
SELECT *
FROM item


        item_name LIKE CONCAT('%', #{itemName}, '%')


        AND item_code LIKE CONCAT('%', #{itemCode}, '%')


        AND specification LIKE CONCAT('%', #{specification}, '%')


        AND unit LIKE CONCAT('%', #{unit}, '%')


        AND warehouse_id = #{warehouseId}


        AND current_stock = #{currentStock}


        AND safe_stock = #{safeStock}


        AND buy_time = #{buyTime}


        AND buy_price = #{buyPrice}


        AND use_department LIKE CONCAT('%', #{useDepartment}, '%')


        AND status = #{status}
